function validate(input) {
  const [{ Boxes = [], Chests = [] }] = input;
  if (Boxes.length === 0) return 'Boxes needs at least one box.';
  const chests = new Set(), boxes = new Set();
  for (const [id, apples, oranges] of Chests) {
    if (id === null) return 'Every chest needs a chest_id.';
    if (chests.has(id)) return `chest_id ${id} appears twice in Chests.`;
    chests.add(id);
    if (apples === null || oranges === null || apples < 0 || oranges < 0) return `Chest ${id} needs non-negative fruit counts.`;
  }
  for (const [id, chest, apples, oranges] of Boxes) {
    if (id === null) return 'Every box needs a box_id.';
    if (boxes.has(id)) return `box_id ${id} appears twice in Boxes.`;
    boxes.add(id);
    if (chest !== null && !chests.has(chest)) return `Box ${id} names chest ${chest}, which is not in Chests.`;
    if (apples === null || oranges === null || apples < 0 || oranges < 0) return `Box ${id} needs non-negative fruit counts.`;
  }
  return null;
}

