function generate(rand, size) {
  const small = size === 'small';
  const chestCount = small ? Math.floor(rand() * 6) : 500, boxCount = small ? 1 + Math.floor(rand() * 8) : 2000;
  const fruit = () => (small ? Math.floor(rand() * 21) : Math.floor(rand() * 1001));
  const Chests = [], ids = [];
  for (let id = 1; ids.length < chestCount; id++) if (!small || rand() < 0.6) { ids.push(id); Chests.push([id, fruit(), fruit()]); }
  const Boxes = [];
  for (let i = 0; i < boxCount; i++) {
    // Some boxes hold no chest; the rest pick any chest, so chests can repeat or go unused.
    const chest = ids.length && rand() < 0.65 ? ids[Math.floor(rand() * ids.length)] : null;
    Boxes.push([small ? 2 * i + 1 + Math.floor(rand() * 2) : i + 1, chest, fruit(), fruit()]);
  }
  return [{ Boxes, Chests }];
}
